import numpy as np

_first = history[0].frame.grid
BG = int(_first[0, 0])
SPRITE = int(_first[2, 10])
STEP = 4 if BG == 5 else 8
# (row, column, colour) of the checkerboard's first two cells, read off
# the scramble screen.
CHECKER = ((8, 40, 3), (8, 41, 4))
START_ENERGY = 20


def initial_state():
    return {'outcome': 'playing', 'energy': START_ENERGY, 'row': 2, 'col': 10, 'scrambled': False, 'trail': []}


def do_move(state, action):
    if action.name == 'UP':
        if state['row'] > 2:
            state['row'] -= STEP
            state['energy'] -= 1
    elif action.name == 'DOWN':
        state['row'] += STEP
        state['energy'] -= 1
    elif action.name == 'LEFT':
        state['energy'] -= 1
        if state['col'] - STEP < 4:
            state['outcome'] = 'lost'
        else:
            state['col'] -= STEP
    elif action.name == 'RIGHT':
        state['col'] += STEP
        state['energy'] -= 1
        if state['col'] >= 30:
            state['outcome'] = 'won'
    elif action.name == 'SPACE':
        state['scrambled'] = not state['scrambled']
        state['energy'] -= 1


def render(state):
    grid = np.full((64, 64), BG, dtype=np.int8)
    if state['scrambled']:
        rows, cols = np.indices((10, 64))
        grid[8:18, :] = np.where((rows + cols) % 2 == 0, CHECKER[0][1], CHECKER[1][2])
    for row, col in state['trail']:
        grid[row, col] = 13
    r, c = state['row'], state['col']
    grid[r:r + 3, c:c + 3] = SPRITE
    grid[63, :START_ENERGY] = -1
    return grid

